import com.greascent.app.StudyEngine;
import java.util.*;
import java.io.*;
import java.time.LocalDate;
public class MemoryTests {
    static int checks;
    static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    static List<StudyEngine.Word> words(){List<StudyEngine.Word> ws=new ArrayList<>();for(int i=0;i<46;i++)ws.add(new StudyEngine.Word("w"+i,"term"+i,"definition "+i,i));return ws;}
    static StudyEngine fresh(){return new StudyEngine(words(),new StudyEngine.State());}
    static void wrong(StudyEngine e,String id,int day){e.s.studyDay=day;e.record(id,"wrong","Meaning MCQ",false,false,day,"");e.grade(id,false,false,false);}
    public static void main(String[] args)throws Exception{
        if(args.length>0){StudyEngine e=new StudyEngine(words(),StudyEngine.load(new File(args[1])));if(args[0].equals("legacy")){check(e.s.previousMistakesHandled!=null&&e.s.retentionDueDay!=null,"old state initializes new memory maps");check(e.s.activeDates.size()==1,"old dated actual attempt migrates streak evidence");check(e.pendingPreviousMistakes().isEmpty(),"correct old attempt creates no invented mistakes");}
            else{check(e.s.session.mode.equals("previous")&&e.s.session.feedback&&e.s.session.holdFeedback,"paused mistake feedback survives process reload");check(e.pendingPreviousMistakes().isEmpty(),"answered pending task stays completed for today");check(e.s.previousMistakesHandled.get("w0")==1,"handled source day persists");check(e.s.activeDates.contains("2026-10-20"),"calendar activity persists");check(e.s.carouselPaused&&e.s.mistakeSlideIndex==2,"slideshow preference persists");}
            System.out.println("Memory "+args[0]+": "+checks+" assertions passed");return;}
        StudyEngine e=fresh();check(e.currentStreak(LocalDate.of(2026,10,26))==0,"fresh app has zero streak");e.noteActivityDate("2026-10-24");e.noteActivityDate("2026-10-25");e.noteActivityDate("2026-10-25");check(e.currentStreak(LocalDate.of(2026,10,26))==2,"yesterday streak remains available before studying today");e.noteActivityDate("2026-10-26");check(e.currentStreak(LocalDate.of(2026,10,26))==3,"study today extends calendar streak once");check(e.currentStreak(LocalDate.of(2026,10,28))==0,"missed calendar day breaks streak");e.noteActivityDate("invalid");e.noteActivityDate(null);check(e.s.activeDates.size()==3,"invalid dates never fabricate streaks");
        check(StudyEngine.entryFraction(.2f,0)==1&&Math.abs(StudyEngine.entryFraction(.2f,1)-.2f)<.0001,"ring starts full and ends at actual value");check(StudyEngine.entryFraction(0,1)==0&&StudyEngine.entryFraction(1,1)==1,"empty and full targets preserved");check(StudyEngine.entryFraction(-5,2)==0&&StudyEngine.entryFraction(5,-1)==1,"animation fractions bounded");
        e=fresh();wrong(e,"w0",1);e.record("w0","term0","Retry · Spelling recall",true,false,1,"");wrong(e,"w0",1);wrong(e,"w1",1);e.record("w2","A","Official GRE · TC",false,false,1,"q");e.record("w3","wrong","Spelling recall",false,true,1,"");check(e.pendingPreviousMistakes().isEmpty(),"today mistakes never insert into today's new quiz");e.s.studyDay=2;check(new HashSet<>(e.pendingPreviousMistakes()).equals(new HashSet<>(Arrays.asList("w0","w1"))),"tomorrow deduplicates vocabulary mistakes and excludes official/replay errors");check(!e.scheduledDueNow().contains("w0"),"pending mistakes excluded from normal scheduled quiz");
        e.startBlock(2,1);check(e.s.session.mode.equals("previous"),"new-day learning opens pending quiz first");check(e.s.session.cards.size()==2&&e.format().equals("Meaning MCQ"),"dedicated quiz contains only mistake words and meaning MCQs");int shuffle=e.s.reviewShuffleCounter;List<String> order=new ArrayList<>(e.s.session.cards);e.startPreviousMistakes();check(e.s.reviewShuffleCounter==shuffle&&order.equals(e.s.session.cards),"resume never reshuffles or loses in-flight order");int total=e.total();String id=e.current();e.answer(e.byId.get(id).term);e.answer("duplicate tap");check(e.s.attempts.stream().filter(a->a.type.startsWith("Previous mistakes")).count()==1,"double selection records once");check(e.total()==total,"pending quiz never inflates new completion");e.nextQuestion();String missed=e.current();e.answer("wrong");check(e.s.session.queue.size()==2,"one pass has no hidden same-day retry insertion");check(e.pendingPreviousMistakes().isEmpty(),"both checked items finish today's pending task");check(e.s.due.get(missed).day==3,"failed pending word scheduled tomorrow");e.nextQuestion();e.startBlock(2,1);check(e.s.session.mode.equals("new")&&e.s.session.cards.size()==e.block(2,1).size(),"new words unlocked after pending answers");e.s.studyDay=3;check(e.pendingPreviousMistakes().equals(Arrays.asList(missed)),"only newly failed word returns next day");
        e=fresh();wrong(e,"w0",1);e.s.studyDay=4;check(e.pendingPreviousMistakes().contains("w0"),"unfinished tasks carry across skipped days");e.record("w0","term0","Scheduled review · Meaning MCQ",true,false,3,"");e.s.attempts.get(1).day=3;check(e.pendingPreviousMistakes().isEmpty(),"previously resolved historical mistake not resurrected");
        e=fresh();wrong(e,"w0",1);e.s.studyDay=2;e.s.mastered.add("w1");e.s.due.put("w1",new StudyEngine.Due(2,"confirmation",0));StudyEngine.Session old=new StudyEngine.Session();old.mode="review";old.quiz=true;old.lessonDay=2;old.cards.addAll(Arrays.asList("w0","w1"));old.queue.addAll(old.cards);old.coreCount=2;e.s.savedSessions.put("review:2",old);e.startReview();check(e.s.session.queue.equals(Arrays.asList("w1")),"old mixed saved review separates pending mistake without deleting history");
        e=fresh();e.confidence("w0",true,false);e.s.coreDone.add("w0");e.s.studyDay=3;e.grade("w0",true,false,false);check(e.s.mastered.contains("w0")&&e.s.retentionDueDay.get("w0")==10,"confirmed word scheduled seven study days later");e.s.studyDay=9;check(e.retentionDue().isEmpty(),"retention not due early");e.s.studyDay=10;check(e.retentionDue().equals(Arrays.asList("w0")),"old word returns after initial seven-day gap");e.startRetention();check(e.s.session.mode.equals("retention")&&e.format().equals("Meaning MCQ"),"retention is separate source-derived meaning quiz");int prior=e.total();e.answer("term0");check(e.s.retentionDueDay.get("w0")==24&&e.total()==prior,"correct retention gets 14-day interval without new progress");e.nextQuestion();e.s.studyDay=24;e.startRetention();e.answer("term0");check(e.s.retentionDueDay.get("w0")==54,"next interval 30 days");e.nextQuestion();e.s.studyDay=54;e.startRetention();e.answer("term0");check(e.s.retentionDueDay.get("w0")==114,"later interval 60 days");e.nextQuestion();e.s.studyDay=114;e.startRetention();e.answer("wrong");check(!e.s.mastered.contains("w0")&&e.s.due.get("w0").day==115,"forgotten old word re-enters next-day relearning");e.nextQuestion();e.s.studyDay=115;check(e.pendingPreviousMistakes().contains("w0"),"retention error enters tomorrow's previous-mistakes quiz");
        e=fresh();for(int i=0;i<20;i++){e.s.mastered.add("w"+i);e.s.retentionDueDay.put("w"+i,1);}e.startRetention();check(e.s.session.cards.size()==10&&new HashSet<>(e.s.session.cards).size()==10,"retention batch capped at ten distinct words");order=new ArrayList<>(e.s.session.cards);e.startRetention();check(order.equals(e.s.session.cards),"retention resume preserves shuffled order");check(!order.equals(Arrays.asList("w0","w1","w2","w3","w4","w5","w6","w7","w8","w9")),"review word order actually shuffles");e.startBlock(1,1);check(e.s.session.cards.get(0).equals("w0")&&e.s.session.cards.get(14).equals("w14"),"new vocabulary ordering remains source-stable");
        e=fresh();wrong(e,"w1",1);wrong(e,"w0",1);wrong(e,"w1",1);e.record("w2","term2","Meaning MCQ",true,false,1,"");check(e.frequentMistakes().get(0).id.equals("w1")&&e.errorCount("w1")==2,"opening slideshow ranks actual incorrect attempts");check(e.frequentMistakes().size()==2,"correct-only words absent from mistake slideshow");
        e.s.screen="practice";e.s.practiceComplete=true;check(e.activity().equals("none"),"completed official set stops practice time");
        e=fresh();wrong(e,"w0",1);e.s.studyDay=2;e.startPreviousMistakes();e.answer("wrong");e.s.session.holdFeedback=true;e.noteActivityDate("2026-10-20");e.s.carouselPaused=true;e.s.mistakeSlideIndex=2;StudyEngine.save(e.s,new File("build/tests/memory-state.bin"));
        System.out.println("Memory behavior: "+checks+" assertions passed");
    }
}
